// ⓪ LA LLAVE Y EL ORIGEN · cadena · puerta · CC#1 · 2026-10-09 · diseño v2 §3.4 + condición 1 de CC#3
// 🔴 ORDEN QUE IMPORTA (condición 1): PRIMERO la llave de despacho, DESPUÉS el cuerpo. La sala no firma el cuerpo y el webhook es una dirección pública:
// quien llegue sin la llave no consigue que se lea ni un campo (ni `target_step_id`). Falla CERRADO: sin la llave en el entorno el flujo queda cerrado.
const w = $input.first().json || {}
const headers = w.headers && typeof w.headers === 'object' ? w.headers : {}
const esperada = String($env.SALA_DISPATCH_KEY || '').trim()
if (!esperada) throw new Error('PUERTA_CERRADA · el motor no tiene la llave de despacho (SALA_DISPATCH_KEY) en su entorno · este flujo paga y queda cerrado hasta que exista · E67')
const recibida = String(headers['x-sala-dispatch-key'] || '')
let ok = recibida.length === esperada.length
for (let i = 0; i < esperada.length; i++) ok = recibida.charCodeAt(i) === esperada.charCodeAt(i) && ok
if (!ok) throw new Error('PUERTA_PROCEDENCIA_INVALIDA · llave de despacho ausente o incorrecta · este flujo paga y solo lo despierta la sala · E67')

// recién ahora se lee el cuerpo
const body = w.body && typeof w.body === 'object' ? w.body : {}
if (typeof body.client_id !== 'string' || !/^[0-9a-fA-F-]{36}$/.test(body.client_id)) throw new Error('PUERTA_CLIENTE_INVALIDO · client_id debe ser un uuid · se DETIENE y no escribe nada')
if (typeof body._journey_id !== 'string' || body._journey_id.trim() === '') throw new Error('PUERTA_SIN_VIAJE · falta _journey_id (lo pone la sala) · se DETIENE y no escribe nada')
if (typeof body.dry_run !== 'boolean') throw new Error('PUERTA_DRY_RUN_AUSENTE · el sobre debe traer dry_run explícito (true o false) · no se asume · se DETIENE antes de gastar')

// el modo lo decide la SALA (`target_step_id` lo escribe el despachador DESPUÉS del payload: no se falsifica desde el cuerpo) · cualquier `modo` del cuerpo se ignora salvo para el vigía y de una lista cerrada
const paso = String(body.target_step_id || '')
let modo = null
if (paso === 'router.dispatch.planeacion/plan-listo.briefear') modo = 'abrir'
else if (paso === 'router.dispatch.cadena/vigia.briefear') {
  if (body.modo !== 'parte' && body.modo !== 'tanda_siguiente') throw new Error('PUERTA_MODO_INVALIDO · el vigía manda parte | tanda_siguiente · llegó ' + JSON.stringify(body.modo))
  modo = body.modo
} else throw new Error('PUERTA_ORIGEN_DESCONOCIDO · target_step_id ' + JSON.stringify(paso) + ' no es de la cadena · no se escribe nada')

return [{
  json: {
    modo,
    client_id: body.client_id,
    tenant_id: body.tenant_id || body.client_id,
    _journey_id: body._journey_id,
    _sala_correlation_id: body._sala_correlation_id || null,
    plan_id: typeof body.plan_id === 'string' ? body.plan_id : null,
    campana_id: typeof body.campana_id === 'string' ? body.campana_id : null,
    lote: typeof body.lote === 'string' ? body.lote : null,
    tanda: Number.isInteger(body.tanda) ? body.tanda : null,
    fila_ids: Array.isArray(body.fila_ids) ? body.fila_ids.filter((x) => typeof x === 'string') : [],
    dry_run: body.dry_run,
    // los simulacros (respuestas enlatadas de los agentes) SOLO existen en seco
    simulacros: body.dry_run === true && body._simulacros && typeof body._simulacros === 'object' ? body._simulacros : null,
    // para la pasarela: el cuerpo ENTERO, sin tocar un campo
    cuerpo_original: JSON.stringify(body),
  },
}]

// ⓪ GUARDA DEL VIAJE · el `_journey_id` y el `client_id` del sobre tienen que existir JUNTOS en la sala (condición 1 de CC#3): si no, no se hace nada
const r = $input.first().json || {}
const b = r.body && typeof r.body === 'object' ? r.body : {}
if (Number(r.statusCode) !== 200) throw new Error('PUERTA_VIAJE_NO_COMPROBABLE · ' + String(b.code || b.error || r.statusCode) + ' · ' + String(b.detalle || b.detail || 'sin detalle') + ' · se DETIENE y no escribe nada')
if (b.existe !== true) throw new Error('PUERTA_VIAJE_NO_EXISTE · el viaje del sobre no existe para este cliente en la sala · se DETIENE y no escribe nada')
return [{ json: $('⓪ Llave y origen').last().json }]

// ⓪ DECIDIR · pasarela o cadena · lo dice el INTERRUPTOR (apagada · ensayo · encendida), no el sobre
// Pasarela = NEUTRAL: reenvía el cuerpo entero a la parte original y no cambia nada observable. Solo el sobre de abrir tiene sentido en pasarela: un sobre del vigía con la cadena apagada se DETIENE (no es de la parte original).
const s = $('⓪ Llave y origen').last().json
const r = $input.first().json || {}
const b = r.body && typeof r.body === 'object' ? r.body : {}
if (Number(r.statusCode) !== 200) throw new Error('PUERTA_ESTADO_NO_COMPROBABLE · ' + String(b.code || b.error || r.statusCode) + ' · ' + String(b.detalle || b.detail || 'sin detalle') + ' · se DETIENE y no escribe nada')
const efectivo = b.modo === 'cadena' ? 'cadena' : 'pasarela'
if (efectivo === 'pasarela' && s.modo !== 'abrir') throw new Error('PUERTA_CADENA_APAGADA · llegó un sobre del vigía (' + s.modo + ') pero la cadena está ' + String(b.estado_cadena) + ' · no se reenvía a la parte original · se DETIENE')
return [{ json: { ...s, efectivo, estado_cadena: b.estado_cadena || null } }]

// PASARELA · ¿SALIÓ? · si el reenvío a la parte original falla, NO se traga el sobre: falla ruidosa (la sala lo ve como `webhook_failed` y reintenta, como hoy)
const r = $input.first().json || {}
const status = Number(r.statusCode)
if (!(status >= 200 && status < 300)) throw new Error('PUERTA_PASARELA_FALLO · la parte original no aceptó el sobre (HTTP ' + String(r.statusCode) + ') · el sobre NO se perdió en silencio')
return [{ json: { resultado: 'pasarela_ok', http: status } }]

// 1 · ¿ABIERTA? · lo que dijo `abrir`: abierta · ya estaba abierta (el mismo sobre dos veces no abre dos campañas) · el plan no coincide (no se escribió nada) · todo lo demás falla ruidoso
const s = $('⓪ Decidir').last().json
const r = $input.first().json || {}
const status = Number(r.statusCode)
const b = r.body && typeof r.body === 'object' ? r.body : {}
if (status === 201 && b.campana && b.campana.id) return [{ json: { ...s, sigue: true, campana_id: b.campana.id, reemplaza_a: b.reemplaza_a || null } }]
if (status === 200 && b.ya_abierta === true) return [{ json: { ...s, sigue: false, resultado: 'cadena_abierta', campana_id: b.campana ? b.campana.id : null, nota: 'ya estaba abierta: no se repite el trabajo' } }]
if (status === 409 && b.resultado === 'plan_no_coincide') return [{ json: { ...s, sigue: false, resultado: 'plan_no_coincide', campana_id: null, nota: String(b.detalle || '') } }]
throw new Error('PUERTA_ABRIR_' + String(b.code || b.error || status) + ' · ' + String(b.detalle || b.detail || 'sin detalle') + ' · se DETIENE')

// 2 · ¿ESTRATEGIA? · terminó bien (o ya estaba hecha) → sigue; si la campaña necesita a Emilio → se corta aquí y se avisa por el cable
const s = $('1 · ¿Abierta?').last().json
const r = $input.first().json || {}
if (r.resultado === 'ok' || r.resultado === 'ya_hecha') return [{ json: { ...s, sigue: true, fechas_pedidas: Array.isArray(r.fechas_pedidas) ? r.fechas_pedidas : [] } }]
return [{ json: { ...s, sigue: false, resultado: 'necesita_humano', alerta: r.alerta || null, nota: 'la estrategia no quedó validada: ' + String(r.resultado) } }]

// 3 · UNA FILA POR TIPO Y AÑO · cada una entra al sub-flujo de fechas con `seco` explícito y, solo en seco, su simulacro
const s = $input.first().json
const sim = s.simulacros && s.simulacros.fechas && typeof s.simulacros.fechas === 'object' ? s.simulacros.fechas : null
return s.fechas_pedidas.map((p) => ({ json: { campana_id: s.campana_id, seco: s.dry_run === true, pais: p.pais, tipo: p.tipo, ambito: p.ambito, anio: p.anio, simulacro: sim } }))

// 3 · JUNTAR · vuelve UN solo ítem (si no, el calendario correría una vez por tipo) · una fecha sin fuente NUNCA detiene la campaña
const s = $('3 · Fechas · ¿hay?').last().json
return [{ json: { ...s, fechas_hechas: $input.all().map((i) => i.json.resultado) } }]

// 4 · ¿CALENDARIO? · el resultado que el cable le cuenta a la sala: la cadena abrió, o la campaña necesita a Emilio
const s = $('2 · ¿Estrategia?').last().json
const r = $input.first().json || {}
const bien = r.resultado === 'ok' || r.resultado === 'ya_hecha'
return [{ json: { ...s, resultado: bien ? 'cadena_abierta' : 'necesita_humano', alerta: bien ? null : (r.alerta || null), nota: bien ? 'estrategia validada y tanda 1 materializada' : 'la tanda 1 no quedó: ' + String(r.resultado) } }]

// PARTE · el lote por fecha que mandó el vigía → la copia de la parte «por filas» (la original no se toca). Nada de decidir aquí: la copia valida el lote.
const s = $input.first().json
if (!s.campana_id || !s.lote || !Array.isArray(s.fila_ids) || s.fila_ids.length === 0) throw new Error('PUERTA_PARTE_SIN_LOTE · el sobre del vigía debe traer campana_id, lote y fila_ids · se DETIENE y no escribe nada')
const cuerpo = { client_id: s.client_id, tenant_id: s.tenant_id, campana_id: s.campana_id, lote: s.lote, fila_ids: s.fila_ids, dry_run: s.dry_run, _journey_id: s._journey_id, _sala_correlation_id: s._sala_correlation_id }
return [{ json: { ...s, cuerpo_parte: JSON.stringify(cuerpo) } }]

// PASARELA · ¿SALIÓ? · si el reenvío a la parte original falla, NO se traga el sobre: falla ruidosa (la sala lo ve como `webhook_failed` y reintenta, como hoy)
const r = $input.first().json || {}
const status = Number(r.statusCode)
if (!(status >= 200 && status < 300)) throw new Error('PUERTA_PASARELA_FALLO · la parte original no aceptó el sobre (HTTP ' + String(r.statusCode) + ') · el sobre NO se perdió en silencio')
return [{ json: { resultado: 'pasarela_ok', http: status } }]

// TANDA SIGUIENTE · el vigía pidió abrir la tanda N de una campaña ya activa · `seco` explícito, simulacro solo en seco
const s = $input.first().json
if (!s.campana_id || !Number.isInteger(s.tanda) || s.tanda < 2) throw new Error('PUERTA_TANDA_INVALIDA · el sobre del vigía debe traer campana_id y tanda ≥ 2 · se DETIENE y no escribe nada')
const sim = s.simulacros && Array.isArray(s.simulacros.calendario) ? s.simulacros.calendario : null
return [{ json: { campana_id: s.campana_id, seco: s.dry_run === true, tanda: s.tanda, simulacro: sim } }]

// TANDA · ¿RESULTADO? · lo que el cable le cuenta a la sala
const s = $('⓪ Decidir').last().json
const r = $input.first().json || {}
const bien = r.resultado === 'ok' || r.resultado === 'ya_hecha'
return [{ json: { ...s, resultado: bien ? 'cadena_abierta' : 'necesita_humano', alerta: bien ? null : (r.alerta || null), nota: 'tanda ' + String(s.tanda) + ': ' + String(r.resultado) } }]

// CABLE · ARMAR EL PEDIDO DE CIERRE · UN solo cable por viaje, y lo manda LA PUERTA con su `worker_id` (los sub-flujos no llaman a la sala): así la sala rotula el viaje como BRIEF
// El resultado ∈ cadena_abierta · lote_briefeado · necesita_humano · plan_no_coincide · pasarela_ok. El que arma el payload es la ruta (`cierre`), con el id de la puerta guardado en cadena_config.
const s = $input.first().json
const ok = ['cadena_abierta', 'lote_briefeado', 'necesita_humano', 'plan_no_coincide', 'pasarela_ok']
if (!ok.includes(s.resultado)) throw new Error('PUERTA_RESULTADO_INVALIDO · ' + JSON.stringify(s.resultado))
const pedido = { accion: 'cierre', resultado: s.resultado, client_id: s.client_id, journey_id: s._journey_id, sala_correlation_id: s._sala_correlation_id, workflow_id: String($workflow.id), workflow_execution_id: String($execution.id) }
if (s.campana_id) pedido.campana_id = s.campana_id
return [{ json: { ...s, pedido_cierre: pedido } }]

// CABLE · ¿VOLVIÓ? · el cable de vuelta no puede ser mudo: si no volvió, la sala nunca se entera de que el viaje terminó
const r = $input.first().json || {}
const b = r.body && typeof r.body === 'object' ? r.body : {}
const volvio = Number(r.statusCode) >= 200 && Number(r.statusCode) < 300 && (b.ok === true || b.kind === 'accepted' || b.kind === 'duplicate' || b.event_id !== undefined)
let corr = null
try { corr = $('⓪ Llave y origen').last().json._sala_correlation_id || null } catch (e) { corr = null }
if (corr && !volvio) throw new Error('CABLE_DE_VUELTA_MUDO · la sala NO se enteró de que el viaje terminó · código ' + String(b.code || b.error || r.statusCode || 'sin código'))
const prev = $('Cable · armar').last().json
return [{ json: { cierre: 'cadena_terminada', resultado: prev.resultado, vuelta_ok: volvio, despachado_por_la_sala: !!corr } }]
